#include <vector>

class Solution {
public:
    int minOperations(std::vector<int>& nums, int k) {
        int xorAll = 0;
        for (int x : nums) xorAll ^= x;
        return __builtin_popcount(xorAll ^ k);
    }
};

class Solution {
    public int minOperations(int[] nums, int k) {
        int xorAll = 0;
        for (int x : nums) xorAll ^= x;
        return Integer.bitCount(xorAll ^ k);
    }
}

var minOperations = function(nums, k) {
    let xorAll = 0;
    for (const x of nums) xorAll ^= x;
    let diff = xorAll ^ k;
    let count = 0;
    while (diff > 0) {
        count += diff & 1;
        diff >>>= 1;
    }
    return count;
};
